pub fn lru(capacity: Int, ops: List[Str]) -> List[Str] {
  var values: Map[Str, Str] = Map {}
  var order: List[Str] = []
  var out: List[Str] = []
  for op in ops {
    let parts = op.split(" ")
    let verb = parts.get_or(0, "")
    let key = parts.get_or(1, "")
    if verb == "put" {
      let value = parts.get_or(2, "")
      if capacity > 0 {
        if values.has(key) == false {
          if values.len() >= capacity {
            let oldest = order.first().unwrap_or("")
            values = values.remove(oldest)
            order = order.drop(1)
          }
        }
        values = values.set(key, value)
        order = order.filter(fn(k) => k != key).push(key)
      }
    } else {
      if values.has(key) {
        out = out.push(values.get(key).unwrap_or("-"))
        order = order.filter(fn(k) => k != key).push(key)
      } else {
        out = out.push("-")
      }
    }
  }
  return out
}
